function homeMapArt(room){return `<img class="world-art sakura-home-art" src="assets/${room==='inside'?'sakura-home-cutaway-v15.jpg':'sakura-home-exterior-v15.jpg'}" width="1448" height="1086" alt="${room==='inside'?'樱花小屋室内：厨房、客厅、卧室、浴室、工作区与衣帽区':'樱花小屋外：粉色房屋、菜园、宠物角与池塘'}" draggable="false">`}
function homePlotPosition(i){return [{x:385,y:735},{x:400,y:775},{x:375,y:825},{x:410,y:865}][i]||{x:400,y:790}}
function renovationMount(g){if(g.player.room==='inside'){const roomItems=[['roomKitchen','厨房 · 一起做饭',435,480,openLivingKitchen],['roomWardrobe','衣帽区 · 自由搭配',850,360,()=>openChibiSelector()],['roomBedroom','卧室 · 休息',1090,435,()=>roomLifeAction('一起在卧室休息了一会儿')],['roomBath','浴室 · 洗漱',485,280,()=>roomLifeAction('在浴室整理好自己，清清爽爽地回到家人身边')],['roomDesk','书桌 · 工作学习',735,230,()=>roomLifeAction('在书桌前工作学习了一会儿')],['roomStorage','储物区 · 食材库存',910,245,()=>openLivingKitchen()]];for(const [id,label,x,y,action]of roomItems){if($('#'+id))continue;const b=document.createElement('button');b.id=id;b.className='world-hotspot room-action';b.textContent=label;b.style.left=x+'px';b.style.top=y+'px';b.onclick=()=>homeWalkTo({x,y},action);$('#gameWorld').append(b)}}if(!$('#homeZoom')){const b=document.createElement('button');b.id='homeZoom';b.className='home-zoom';b.textContent='视野 80%';b.onclick=()=>{g.zoom=g.zoom===1?.65:g.zoom===.65?.8:1;b.textContent='视野 '+Math.round(g.zoom*100)+'%';homePosition(g)};$('.home-game').append(b)}}
function roomLifeAction(text){try{livingCommit(wallet,livingEvent(living,profile.name+'与在场来客'+text));livingBubble('me',text);toast('已记录这段家园经历')}catch(e){toast(e.message)}}
